package com.soulbrowser.app
import org.mozilla.geckoview.GeckoSession
import org.mozilla.geckoview.GeckoSessionSettings
enum class UserAgentProfile(val label:String,val overrideString:String?){ DEFAULT_MOBILE("Soul Mobile (Default)",null),DESKTOP_LINUX("Desktop Firefox","Mozilla/5.0 (X11; Linux x86_64; rv:150.0) Gecko/20100101 Firefox/150.0"),DESKTOP_CHROME("Desktop Chrome","Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/134.0.0.0 Safari/537.36"),MOBILE_SAFARI("iPhone Safari","Mozilla/5.0 (iPhone; CPU iPhone OS 18_3 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.3 Mobile/15E148 Safari/604.1") }
object UserAgentSpoofer { fun apply(session:GeckoSession?,profile:UserAgentProfile,reload:Boolean=true){ val s=session?:return; val d=profile==UserAgentProfile.DESKTOP_LINUX||profile==UserAgentProfile.DESKTOP_CHROME; s.settings.userAgentOverride=profile.overrideString; s.settings.userAgentMode=if(d)GeckoSessionSettings.USER_AGENT_MODE_DESKTOP else GeckoSessionSettings.USER_AGENT_MODE_MOBILE; s.settings.viewportMode=if(d)GeckoSessionSettings.VIEWPORT_MODE_DESKTOP else GeckoSessionSettings.VIEWPORT_MODE_MOBILE; if(reload)s.reload() } }